import 'package:cloud_firestore/cloud_firestore.dart';
import 'package:firebase_auth/firebase_auth.dart';
import 'package:firebase_core/firebase_core.dart';
import 'package:flutter/material.dart';

Future<void> main() async {
  WidgetsFlutterBinding.ensureInitialized();
    String? startupError;
      try {
          await Firebase.initializeApp();
              if (FirebaseAuth.instance.currentUser == null) {
                    await FirebaseAuth.instance.signInAnonymously();
                        }
                          } catch (e) {
                              startupError = e.toString();
                                }
                                  runApp(ChildApp(startupError: startupError));
                                  }

                                  class ChildApp extends StatelessWidget {
                                    const ChildApp({super.key, this.startupError});
                                      final String? startupError;

                                        @override
                                          Widget build(BuildContext context) {
                                              return MaterialApp(
                                                    title: 'Child App',
                                                          theme: ThemeData(colorSchemeSeed: Colors.teal, useMaterial3: true),
                                                                home: startupError != null
                                                                          ? Scaffold(
                                                                                        body: Center(
                                                                                                          child: Padding(
                                                                                                                                padding: const EdgeInsets.all(24),
                                                                                                                                                      child: Text('Startup error ❌\n$startupError'))))
                                                                                                                                                                : const ChildHome(),
                                                                                                                                                                    );
                                                                                                                                                                      }
                                                                                                                                                                      }

                                                                                                                                                                      class ChildHome extends StatelessWidget {
                                                                                                                                                                        const ChildHome({super.key});

                                                                                                                                                                          @override
                                                                                                                                                                            Widget build(BuildContext context) {
                                                                                                                                                                                final uid = FirebaseAuth.instance.currentUser!.uid;
                                                                                                                                                                                    return StreamBuilder<DocumentSnapshot<Map<String, dynamic>>>(
                                                                                                                                                                                          stream:
                                                                                                                                                                                                    FirebaseFirestore.instance.collection('children').doc(uid).snapshots(),
                                                                                                                                                                                                          builder: (context, snap) {
                                                                                                                                                                                                                  if (snap.hasError) {
                                                                                                                                                                                                                            return Scaffold(body: Center(child: Text('Error: ${snap.error}')));
                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                            if (!snap.hasData) {
                                                                                                                                                                                                                                                      return const Scaffold(
                                                                                                                                                                                                                                                                    body: Center(child: CircularProgressIndicator()));
                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                    final data = snap.data!.data();
                                                                                                                                                                                                                                                                                            return data == null ? const PairPage() : ConnectedPage(data: data);
                                                                                                                                                                                                                                                                                                  },
                                                                                                                                                                                                                                                                                                      );
                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                        class PairPage extends StatefulWidget {
                                                                                                                                                                                                                                                                                                          const PairPage({super.key});

                                                                                                                                                                                                                                                                                                            @override
                                                                                                                                                                                                                                                                                                              State<PairPage> createState() => _PairPageState();
                                                                                                                                                                                                                                                                                                              }

                                                                                                                                                                                                                                                                                                              class _PairPageState extends State<PairPage> {
                                                                                                                                                                                                                                                                                                                final _code = TextEditingController();
                                                                                                                                                                                                                                                                                                                  bool _busy = false;
                                                                                                                                                                                                                                                                                                                    String? _error;

                                                                                                                                                                                                                                                                                                                      Future<void> _connect() async {
                                                                                                                                                                                                                                                                                                                          final code = _code.text.trim();
                                                                                                                                                                                                                                                                                                                              if (code.length != 8) {
                                                                                                                                                                                                                                                                                                                                    setState(() => _error = '৮ অঙ্কের code দিন');
                                                                                                                                                                                                                                                                                                                                          return;
                                                                                                                                                                                                                                                                                                                                              }
                                                                                                                                                                                                                                                                                                                                                  setState(() {
                                                                                                                                                                                                                                                                                                                                                        _busy = true;
                                                                                                                                                                                                                                                                                                                                                              _error = null;
                                                                                                                                                                                                                                                                                                                                                                  });
                                                                                                                                                                                                                                                                                                                                                                      try {
                                                                                                                                                                                                                                                                                                                                                                            final db = FirebaseFirestore.instance;
                                                                                                                                                                                                                                                                                                                                                                                  final uid = FirebaseAuth.instance.currentUser!.uid;
                                                                                                                                                                                                                                                                                                                                                                                        final codeRef = db.collection('pairingCodes').doc(code);
                                                                                                                                                                                                                                                                                                                                                                                              await db.runTransaction((tx) async {
                                                                                                                                                                                                                                                                                                                                                                                                      final snap = await tx.get(codeRef);
                                                                                                                                                                                                                                                                                                                                                                                                              final d = snap.data();
                                                                                                                                                                                                                                                                                                                                                                                                                      if (d == null || d['used'] == true) {
                                                                                                                                                                                                                                                                                                                                                                                                                                throw StateError('Code ভুল বা আগেই ব্যবহার হয়েছে');
                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                tx.set(db.collection('children').doc(uid), {
                                                                                                                                                                                                                                                                                                                                                                                                                                                          'parentUid': d['parentUid'],
                                                                                                                                                                                                                                                                                                                                                                                                                                                                    'childName': d['childName'],
                                                                                                                                                                                                                                                                                                                                                                                                                                                                              'code': code,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        'pairedAt': FieldValue.serverTimestamp(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        tx.update(codeRef, {'used': true, 'childUid': uid});
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  } on StateError catch (e) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (mounted) setState(() => _error = e.message);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            } on FirebaseException {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  if (mounted) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          setState(() => _error = 'Code ভুল, মেয়াদ শেষ, বা আগেই ব্যবহার হয়েছে');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    } finally {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          if (mounted) setState(() => _busy = false);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  @override
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    Widget build(BuildContext context) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        return Scaffold(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              appBar: AppBar(title: const Text('Connect to Parent')),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    body: ListView(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            padding: const EdgeInsets.all(24),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    children: [
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              const Text('Parent-এর দেওয়া ৮ অঙ্কের code লিখুন'),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const SizedBox(height: 12),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  TextField(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              controller: _code,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          keyboardType: TextInputType.number,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      maxLength: 8,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  decoration: const InputDecoration(labelText: 'Pairing code'),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      if (_error != null)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  Padding(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                padding: const EdgeInsets.symmetric(vertical: 8),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              child: Text(_error!, style: const TextStyle(color: Colors.red)),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const SizedBox(height: 12),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              FilledButton(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          onPressed: _busy ? null : _connect,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      child: _busy
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      ? const SizedBox(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          height: 20,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              width: 20,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  child: CircularProgressIndicator(strokeWidth: 2))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  : const Text('Connect'),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    ],
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                class ConnectedPage extends StatelessWidget {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  const ConnectedPage({super.key, required this.data});
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    final Map<String, dynamic> data;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      @override
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        Widget build(BuildContext context) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            final uid = FirebaseAuth.instance.currentUser!.uid;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                final name = data['childName'] ?? '';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    return Scaffold(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          appBar: AppBar(title: const Text('Child App')),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                body: Center(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        child: Padding(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  padding: const EdgeInsets.all(24),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            child: Column(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        mainAxisSize: MainAxisSize.min,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    children: [
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  const Icon(Icons.link, size: 64, color: Colors.green),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const SizedBox(height: 16),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              Text('Parent-এর সাথে যুক্ত ✅',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                style: Theme.of(context).textTheme.titleLarge),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              const SizedBox(height: 8),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            Text('নাম: $name'),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          const SizedBox(height: 32),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        OutlinedButton(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        onPressed: () => FirebaseFirestore.instance
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            .collection('children')
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                .doc(uid)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    .delete(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    child: const Text('Disconnect'),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              ],
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            